function plainFn(){return typeof this}print("plain function this (non-strict, global-ish):",plainFn());const obj={value:42,getValue:function(){return this.value},getValueArrow:()=>typeof this,makeArrowGetter:function(){return()=>this.value}};function standalone(){return this&&this.value}print("method this:",obj.getValue()),print("arrow at object-literal position ignores obj:",obj.getValueArrow()),print("arrow defined inside method captures method this:",obj.makeArrowGetter()()),print("call:",standalone.call({value:"via-call"})),print("apply:",standalone.apply({value:"via-apply"}));const bound=standalone.bind({value:"via-bind"});function Counter(){this.count=0,this.increment=function(){return this.count++,this.count}}print("bind:",bound());const c1=new Counter,detached=c1.increment;print("detached loses this:",function(){try{return detached()}catch(t){return"threw:"+t.constructor.name}}()),print("bound retains this:",detached.bind(c1)());